L={int(t[:-1]):t[-1] for t in seq.split()}
d=pd.read_csv('data/pilot12.csv'); assert sorted(L)==list(d.id), (len(L),len(d))
name={'F':'사실 전달','C':'갈등','R':'원인·책임','N':'부정 결과·우려','A':'긍정 성과','P':'대응·조치','O':'기타'}
d['frame']=d.id.map(L).map(name)
d['date']=d['date'].astype(str).str.replace(r'(\d{4})(\d{2})(\d{2})',r'\1-\2-\3',regex=True)
d['outlet_type']=d.outlet.map(lambda o:'방송' if o in {'KBS','MBC','SBS','YTN'} else '경제지' if o in {'매일경제','한국경제'} else '종합일간지')
d.loc[d.eid=='E09','event']='코스피 급락과 반등'
kw={'E01':'선관위 특검 · 투표지 검증 · 올림픽공원 · 투표함 반출','E02':'조작기소 · 특검법 · 법사위 · 당론 · 본회의',
'E03':'윤석열 · 선거법 2심 · 당선무효형 · 397억 반환','E04':'김기현 · 김건희 · 로저비비에 · 1심 무죄','E05':'수출 · 1조 달러 · 반도체 · 무역수지',
'E06':'퇴직급여 · 사외적립 · 의무화 · 기금형 퇴직연금','E07':'SK하이닉스 · 영업이익 · 주주환원 · 배당','E08':'예산안 · 821조 · 시정연설 · 모두의 성장',
'E09':'코스피 · 사이드카 · 급락 · 급등','E10':'가상자산 · 과세 유예 · 당정 · 김민석','E11':'진성준 · 미국 비자 · 국방위원장 · 한미동맹',
'E12':'수능 · 스마트안경 · 부정행위 · 응시정지','E13':'소비자물가 · 2.8% · 석유류 · 가공식품','E14':'결제주기 · T+1 · 한국거래소 · 2028년','E15':'아주대병원 · 소아응급 · 압수수색 · 사직'}
d['keywords']=d.eid.map(kw)
d=d[['id','eid','event','keywords','date','outlet','outlet_type','headline','frame']]
d.to_csv('/home/claude/headlines_week.csv',index=False)
